{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Teriflunomide, an orally administered lipophilic anilide with structural resemblance to the query's N-aryl amide, has absolute oral bioavailability approaching 100% in fasted healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Leflunomide, a related lipophilic anilide prodrug of teriflunomide, has oral bioavailability as high as 80% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Apatinib, an oral anilide-containing drug, shows good oral bioavailability and tolerance in humans, supporting that this structural class can achieve adequate systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Zeaxanthin, a highly lipophilic conjugated polyene, can show high oral bioavailability when ingested with fat, supporting absorption of lipophilic retinoid-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic retinoid-like N-aryl amide. Transferable evidence from structurally related anilide drugs and lipophilic conjugated molecules consistently indicates high oral bioavailability, with no affirmative evidence of F < 20%. Therefore the prediction is high (F >= 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is provided.",
    "No experimental record in the visible evidence set reports low oral bioavailability for a close retinoid analogue.",
    "The influence of the query's phenolic group on first-pass conjugation is not directly addressed by the available records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

